"""Variable contract — H4, M1, M2.

H4: utils.set_variables.dry_run returns a dict with a ``variables`` key
    whose value is a dict (the sole producer of planning variables).
M1: build_action_plan against a REAL ExecutionContext does not mutate
    ``exec_ctx.variables``; the isolation copy is observable through the
    rendered template path.
M2: RESERVED_VARIABLES are filtered out of planning_vars in
    ``_merge_planning_vars``; a spy path_template sees no reserved keys.

CWD note (M1): the ``exec_ctx`` fixture roots its scope at ``tmp_path``
but does not chdir. ``validate_proposal`` resolves relative payload paths
against CWD, so M1 chdirs to ``tmp_path`` before planning — otherwise the
real ScopeManager rejects ``1.txt`` as out-of-scope. That would be a
test-environment artefact, not a violation of the isolation contract this
test is meant to pin.

M2 does NOT need the chdir: the graph has no fs-node consuming a path,
so ``extract_paths`` returns ``()`` and the scope check never fires.

"""

from __future__ import annotations

import dataclasses
from pathlib import Path

import pytest

from lokdocsqr.core.models import (
    EdgeSpec,
    NodeSpec,
    NodeState,
    PolicyAction,
    PolicyDecision,
    PortSpec,
    ResolvedGraph,
    WorkflowDocument,
    WorkflowMetadata,
)
from lokdocsqr.core.planning.builder import build_action_plan
from lokdocsqr.nodes.fs_ops.write_file import WriteFileNode
from lokdocsqr.nodes.utils.path_template import PathTemplateNode
from lokdocsqr.nodes.utils.set_variables import SetVariablesNode


class AllowPolicy:
    def decide(self, proposal):
        return PolicyDecision(PolicyAction.ALLOW, "allow", proposal)


# ---------------------------------------------------------------------------
# H4 — set_variables emits a dict under the ``variables`` key
# ---------------------------------------------------------------------------

def test_set_variables_emits_variables_dict(exec_ctx) -> None:
    result = SetVariablesNode().dry_run(exec_ctx, {"variables": {"a": 1}})
    assert isinstance(result, dict)
    assert "variables" in result, (
        "set_variables.dry_run must return a dict with a 'variables' key"
    )
    assert isinstance(result["variables"], dict), (
        "set_variables.dry_run['variables'] must be a dict"
    )


# ---------------------------------------------------------------------------
# M1 — real ExecutionContext isolation
# ---------------------------------------------------------------------------

def test_isolated_ctx_with_real_execution_context(
    exec_ctx, tmp_path, monkeypatch
) -> None:
    if not dataclasses.is_dataclass(exec_ctx):
        pytest.skip(
            "exec_ctx fixture is not a dataclass — _isolated_ctx is a no-op "
            "for duck-typed contexts (7d-a D.3); real ExecutionContext is a "
            "dataclass, so this test only runs when the fixture provides one"
        )

    # Align CWD with scope root so validate_proposal accepts the rendered
    # relative path. Does not touch _isolated_ctx semantics — this test
    # pins ctx.variables isolation, not scope handling.
    monkeypatch.chdir(tmp_path)

    before = dict(exec_ctx.variables)

    n0 = NodeSpec(
        id="n0", type="utils.set_variables",
        params={"variables": {"x": 1}},
    )
    n1 = NodeSpec(
        id="n1", type="utils.path_template",
        params={"template": "{x}.txt"},
    )
    n2 = NodeSpec(id="n2", type="fs.write_file", params={"content": "hi"})
    edges = [
        EdgeSpec(
            id="e0", source="n0", target="n1",
            source_port="variables", target_port="variables",
        ),
        EdgeSpec(
            id="e1", source="n1", target="n2",
            source_port="path_template", target_port="path_template",
        ),
    ]
    doc = WorkflowDocument(
        spec_version="1.0",
        metadata=WorkflowMetadata(id="test"),
        nodes=[n0, n1, n2],
        edges=edges,
    )
    graph = ResolvedGraph(
        document=doc,
        ordered_node_ids=["n0", "n1", "n2"],
        handlers={
            "n0": SetVariablesNode(),
            "n1": PathTemplateNode(),
            "n2": WriteFileNode(),
        },
        states={
            "n0": NodeState.ENABLED,
            "n1": NodeState.ENABLED,
            "n2": NodeState.ENABLED,
        },
    )

    plan = build_action_plan(graph, exec_ctx, AllowPolicy())
    assert not plan.blocked, plan.errors
    assert plan.proposals, "no proposals produced"

    last = plan.proposals[-1]
    assert Path("1.txt") in {Path(p) for p in last.target_paths}, (
        f"last proposal target_paths={last.target_paths!r}, expected '1.txt'"
    )

    # The real ExecutionContext must not be mutated by build_action_plan.
    assert exec_ctx.variables == before, (
        f"exec_ctx.variables was mutated: {before!r} -> {exec_ctx.variables!r}"
    )
    assert "x" not in exec_ctx.variables, (
        "'x' leaked from planning_vars into exec_ctx.variables"
    )


# ---------------------------------------------------------------------------
# M2 — reserved keys filtered in planning_vars (negative case)
# ---------------------------------------------------------------------------

def test_reserved_keys_filtered_in_planning(exec_ctx) -> None:
    captured_ctx: list = []

    class _SpyPathTemplate(PathTemplateNode):
        def dry_run(self, ctx, payload):
            captured_ctx.append(ctx)
            return super().dry_run(ctx, payload)

    n0 = NodeSpec(
        id="n0", type="utils.set_variables",
        params={"variables": {"run_id": "evil", "ok": "x"}},
    )
    n1 = NodeSpec(
        id="n1", type="utils.path_template",
        params={"template": "{ok}.txt"},
    )
    edges = [
        EdgeSpec(
            id="e0", source="n0", target="n1",
            source_port="variables", target_port="variables",
        ),
    ]
    doc = WorkflowDocument(
        spec_version="1.0",
        metadata=WorkflowMetadata(id="test"),
        nodes=[n0, n1],
        edges=edges,
    )
    graph = ResolvedGraph(
        document=doc,
        ordered_node_ids=["n0", "n1"],
        handlers={"n0": SetVariablesNode(), "n1": _SpyPathTemplate()},
        states={"n0": NodeState.ENABLED, "n1": NodeState.ENABLED},
    )

    plan = build_action_plan(graph, exec_ctx, AllowPolicy())
    assert not plan.blocked, plan.errors

    assert "run_id" not in exec_ctx.variables, (
        "'run_id' leaked into exec_ctx.variables"
    )

    assert captured_ctx, "spy path_template.dry_run was never called"
    spy_ctx = captured_ctx[-1]
    spy_vars = getattr(spy_ctx, "variables", {}) or {}
    assert "run_id" not in spy_vars, (
        f"reserved key 'run_id' leaked into planning_vars: {spy_vars!r}"
    )
